void CVideo::RestoreImage(const char* img, bool raw)
{
	if (!raw)
	{
		return;
	}
	
	void* buf = NULL;
	CFileIO file;
	if (file.Open(img))
	{
		buf = zmalloc(file.m_filesize);
		file.fread(buf, file.m_filesize);
		file.Close();
		zfree(buf);
	}
}
